  <style>
    * { box-sizing: border-box; -webkit-tap-highlight-color: transparent; }
    html, body {
      margin: 0;
      width: 100%;
      height: 100%;
      overflow: hidden;
      background: linear-gradient(180deg, #ffe8d9 0%, #ffd2cc 45%, #ffc4b8 100%);
      font-family: Arial, Helvetica, sans-serif;
